import { io } from "socket.io-client";

const SOCKET_URL = process.env.REACT_APP_BACKEND_URL || "http://localhost:5001";

let socket = null;

export const initSocket = () => {
  if (!socket) {
    socket = io(SOCKET_URL, {
      transports: ["websocket", "polling"],
      reconnection: true,
      reconnectionAttempts: 10,
      reconnectionDelay: 1000,
    });

    socket.on("connect", () => {
      console.log("WebSocket connected to backend:", socket.id);
      const sellerId = localStorage.getItem("sellerId");
      if (sellerId) {
        socket.emit("joinSellerRoom", sellerId);
      }
      const userId = localStorage.getItem("userId") || JSON.parse(localStorage.getItem("user") || "{}")?.id || JSON.parse(localStorage.getItem("user") || "{}")?._id;
      if (userId) {
        socket.emit("joinBuyerRoom", userId);
      }
    });

    socket.on("disconnect", () => {
      console.log("WebSocket disconnected");
    });
  }
  return socket;
};

export const getSocket = () => {
  if (!socket) {
    return initSocket();
  }
  return socket;
};

export const joinSellerRoom = (sellerId) => {
  const s = getSocket();
  if (s && sellerId) {
    s.emit("joinSellerRoom", sellerId);
  }
};

export const joinBuyerRoom = (buyerId) => {
  const s = getSocket();
  if (s && buyerId) {
    s.emit("joinBuyerRoom", buyerId);
  }
};
